(() => {
'use strict';
const KEY = 'percorsocane_1_0_data';
const DAY=86400000, HOUR=3600000;
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=> 'id'+Math.random().toString(36).slice(2,10)+Date.now().toString(36);
const isoLocal=d=>{const dt=new Date(d);return `${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}T${String(dt.getHours()).padStart(2,'0')}:${String(dt.getMinutes()).padStart(2,'0')}`};
const dateKey=d=>isoLocal(d).slice(0,10);
const fmtDate=s=>{if(!s)return '—';const d=new Date(s);return isNaN(+d)?esc(s):new Intl.DateTimeFormat('it-IT',{day:'2-digit',month:'short',year:'numeric'}).format(d)};
const fmtDateTime=s=>{if(!s)return '—';const d=new Date(s);return isNaN(+d)?esc(s):new Intl.DateTimeFormat('it-IT',{weekday:'short',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(d)};
const euro=n=>new Intl.NumberFormat('it-IT',{style:'currency',currency:'EUR'}).format(Number(n)||0);
const plusDays=(n,h=17)=>{const d=new Date();d.setDate(d.getDate()+n);d.setHours(h,0,0,0);return isoLocal(d)};
const weekKey=d=>{const dt=new Date(d),dow=(dt.getDay()+6)%7;dt.setDate(dt.getDate()-dow);return dateKey(dt)};
const verifyPhoto=s=>/^data:image\/(?:jpeg|png|webp);base64,[a-z0-9+/=]+$/i.test(s||'');
const field=(key,label,type='text',opts={},more={})=>({key,label,type,...(Array.isArray(opts)?{options:opts}:opts),...more});
const YESNO=['','Sì','No'];
const CONFIG={
 identity:{title:'Anagrafica e storia',help:'Dati del cane, provenienza, salute e precedenti esperienze.',fields:[
 field('name','Nome del cane'),field('sex','Sesso','select',['','Maschio','Femmina']),field('sexStatus','Stato riproduttivo','select',['','Intero','Sterilizzato / Castrato']),field('breed','Razza o mix di razze'),field('birthDate','Data di nascita (se conosciuta)','date'),field('ageYears','Età stimata (anni)','number',{min:'0',max:'35',step:'.1'}),field('weightKg','Peso (kg)','number',{min:'0',max:'200',step:'.1'}),field('origin','Provenienza','select',['','Allevamento','Privato','Canile','Associazione','Pensione','Strada / ex randagio','Altro']),field('originNotes','Note sulla provenienza','textarea',{full:true}),field('microchip','Microchip','select',['','Presente','Assente','Da verificare']),field('microchipNumber','Numero microchip (facoltativo)'),field('residenceArea','Contesto di residenza','select',['','Urbano','Semiurbano','Rurale / campagna','Altro']),field('housing','Ambiente di vita','select',['','Appartamento','Casa con giardino','Casa con terrazzo','Villa','Campagna','Altro']),field('health','Stato di salute e patologie','textarea',{full:true}),field('currentDiet','Alimentazione attuale','textarea',{full:true}),field('previousTraining','Percorsi con altri professionisti','select',YESNO),field('previousTrainingNotes','Dettagli percorsi precedenti','textarea',{full:true}),field('clinicalUpdates','Situazioni cliniche, interventi o eventi da monitorare','textarea',{full:true}),field('vet','Veterinario di riferimento'),field('entryAge','Età di ingresso nella famiglia attuale'),field('previousFamilies','Famiglie precedenti','select',YESNO),field('firstDog','È il primo cane del nucleo familiare?','select',YESNO),field('trauma','Eventi difficili / traumi riferiti (solo informazioni necessarie)','textarea',{full:true})]},
 family:{title:'Sistema familiare e relazionale',help:'Contesto del nucleo familiare: descrivere esigenze pratiche senza inserire diagnosi delle persone.',fields:[
 field('familyCount','Numero di componenti del nucleo','number',{min:'1',max:'50',step:'1'}),field('children','Presenza di bambini','select',YESNO),field('pregnancy','Presenza di gravidanza rilevante per la gestione pratica','select',YESNO),field('supportNeeds','Esigenze di accessibilità / supporto nella convivenza','select',YESNO),field('otherPets','Altri cani o animali presenti','textarea',{full:true}),field('familyDifficulties','Difficoltà relazionali con componenti del nucleo','textarea',{full:true}),field('referencePerson','Figura di riferimento per il cane'),field('familyDynamics','Dinamiche e risorse familiari','textarea',{full:true})]},
 emotion:{title:'Profilo emotivo e motivazionale',help:'Osservazioni professionali contestualizzate. I punteggi 1–5 descrivono competenze osservate, non diagnosi.',fields:[
 field('prevailingEmotion','Stato emotivo prevalente osservato','textarea',{full:true}),field('familyConflict','Conflittualità con il nucleo familiare (situazioni e frequenza)','textarea',{full:true}),field('emotionalRecovery','Recupero dopo attivazione emotiva','score'),field('stimulusManagement','Gestione della sensibilità agli stimoli','score'),field('frustrationTolerance','Tolleranza alla frustrazione','score'),field('selfRegulation','Autoregolazione','score'),field('waitingAbility','Gestione dell’attesa','score'),field('uncertaintyResponse','Gestione dell’incertezza','score'),field('newSituationsConfidence','Sicurezza in situazioni nuove','score'),field('prevailingMotivations','Motivazioni prevalenti','textarea',{full:true}),field('interests','Interessi individuali','textarea',{full:true}),field('rewardingActivities','Attività gratificanti','textarea',{full:true}),field('interactionModulation','Modulazione / interruzione delle interazioni','score'),field('distressTriggers','Fattori che generano disagio','textarea',{full:true}),field('copingStrategies','Strategie spontanee di gestione','textarea',{full:true}),field('dischargeActivities','Attività di scarico o decompressione','textarea',{full:true})]},
 skills:{title:'Competenze osservate',help:'Scala descrittiva 1–5: 1 = necessita forte supporto, 5 = buona autonomia nel contesto osservato.',fields:[
 field('intraspecific','Competenze sociali con altri cani','score'),field('interspecific','Competenze sociali con altre specie / persone','score'),field('exploration','Capacità esplorative','score'),field('cognitive','Capacità cognitive','score'),field('problemSolving','Problem solving','score'),field('learning','Capacità di apprendimento','score'),field('autonomy','Autonomia','score'),field('resources','Gestione delle risorse','score'),field('collaboration','Capacità di collaborazione','score'),field('adaptation','Adattamento ai cambiamenti','score'),field('skillNotes','Osservazioni contestuali','textarea',{full:true})]},
 routine:{title:'Routine e benessere',help:'Raccogliere la situazione attuale senza usare automaticamente i dati come giudizi sul benessere.',fields:[
 field('walkDuration','Durata media delle uscite'),field('walkType','Tipologia, frequenza e contesto delle uscite','textarea',{full:true}),field('movement','Opportunità di libertà e movimento','textarea',{full:true}),field('sleepHours','Ore indicative di riposo nelle 24 ore','number',{min:'0',max:'24',step:'.5'}),field('sleepQuality','Qualità del sonno e luoghi di riposo','textarea',{full:true}),field('aloneTime','Tempo abituale trascorso in solitudine'),field('handling','Manipolazioni / contatto fisico: presenza e frequenza','textarea',{full:true}),field('dailyNotes','Altre osservazioni sulla routine','textarea',{full:true})]},
 work:{title:'Valutazione e piano professionale',help:'Sezione riservata all’educatore nella futura versione multiutente. Qui la separazione è solo dimostrativa.',fields:[
 field('character','Personalità e carattere osservati','textarea',{full:true}),field('biggestDifficulties','Difficoltà maggiori','textarea',{full:true}),field('lessonRisks','Criticità specifiche durante le lezioni (es. controllo del movimento, morsicature)','textarea',{full:true}),field('ownerNotes','Note riservate sul proprietario / sulla gestione della relazione','textarea',{full:true}),field('behaviourVet','Necessaria collaborazione con veterinario comportamentalista','select',['','Da valutare','Sì','No']),field('otherProfessional','Collaborazione con ESCAC o altri professionisti','select',['','Da valutare','Sì','No']),field('referralNotes','Motivazioni e contatti per invio ad altri professionisti','textarea',{full:true}),field('otherAreas','Ulteriori aspetti su cui lavorare','textarea',{full:true}),field('approach','Impostazione del percorso / indicazioni operative','textarea',{full:true})]}
};
function seed(){return {
 version:1,createdAt:new Date().toISOString(),clients:[{id:'c-demo',name:'Sara Bianchi (demo)',email:'',phone:''}],
 dogs:[{id:'d-demo',clientId:'c-demo',photo:'',identity:{name:'Milo',sex:'Maschio',sexStatus:'Intero',breed:'Meticcio',ageYears:'3',weightKg:'19',origin:'Canile',microchip:'Presente',residenceArea:'Semiurbano',housing:'Casa con giardino',health:'Nessuna condizione segnalata nel profilo dimostrativo',currentDiet:'Alimentazione commerciale',vet:'Veterinario di fiducia (demo)'},family:{familyCount:'3',children:'No',otherPets:'Nessuno',referencePerson:'Sara'},emotion:{prevailingEmotion:'Attento all’ambiente; osservazione illustrativa, non clinica',emotionalRecovery:'3',stimulusManagement:'2',frustrationTolerance:'3',selfRegulation:'3',waitingAbility:'2',newSituationsConfidence:'3'},skills:{intraspecific:'3',interspecific:'3',exploration:'4',cognitive:'4',problemSolving:'3',learning:'4',autonomy:'3',resources:'3',collaboration:'4',adaptation:'3'},routine:{walkDuration:'3 uscite da 20–40 minuti',walkType:'Passeggiate urbane e in area verde',sleepHours:'13',aloneTime:'1–2 ore al giorno'},work:{character:'Curioso e vigile; valutazione illustrativa',biggestDifficulties:'Gestione dell’attesa e degli stimoli in passeggiata',lessonRisks:'Rivedere le reazioni ai movimenti rapidi',behaviourVet:'Da valutare'}}],
 slots:[{id:'s1',start:plusDays(4,16),duration:60,location:'Campo educativo',fee:45},{id:'s2',start:plusDays(6,17),duration:60,location:'Incontro individuale',fee:45},{id:'s3',start:plusDays(9,10),duration:60,location:'Campo educativo',fee:45}],
 appointments:[{id:'a-demo',slotId:'s3',dogId:'d-demo',clientId:'c-demo',status:'confirmed',payment:'unpaid',requestedAt:new Date().toISOString()}],
 notices:[],
 goals:[{id:'g1',dogId:'d-demo',title:'Gestione dell’attesa',description:'Attendere brevemente in contesti progressivamente più stimolanti',progress:40,area:'Autoregolazione',targetDate:''},{id:'g2',dogId:'d-demo',title:'Passeggiata più serena',description:'Ridurre la difficoltà nella gestione di stimoli intensi',progress:65,area:'Routine',targetDate:''}],
 checkins:[{id:'w1',dogId:'d-demo',week:weekKey(new Date(Date.now()-7*DAY)),score:3,notes:'Settimana dimostrativa: esercizi di attesa in contesto tranquillo',homework:'Sessioni brevi, senza forzare.'}],
 journal:[{id:'j1',dogId:'d-demo',date:dateKey(new Date(Date.now()-5*DAY)),activity:'Osservazione della gestione dell’attesa e passeggiata in area tranquilla.',next:'Lavorare sul recupero dopo gli stimoli.',difficulty:'Forte attenzione ai movimenti rapidi.',privateNote:'Nota interna di esempio',share:true}]
 }}
let db;
try {db=JSON.parse(localStorage.getItem(KEY)||'null'); if(!db||!Array.isArray(db.clients)||!Array.isArray(db.dogs))db=seed()} catch {db=seed()}
if(!Array.isArray(db.notices))db.notices=[];
const ui={view:'dashboard',role:'educator',clientId:db.clients[0]?.id||null,dogId:db.dogs[0]?.id||null,tab:'identity',appointmentFilter:'all',modal:null,toast:''};
let toastTimeout;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(e){notify('Spazio locale esaurito: esporta un backup o rimuovi immagini pesanti.');return false}}
if(!localStorage.getItem(KEY)) save();
function notify(s){ui.toast=s;render();clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>{ui.toast='';const t=$('.toast');if(t)t.remove()},3400)}
function isEducator(){return ui.role==='educator'}
function myDogs(){return isEducator()?db.dogs:db.dogs.filter(d=>d.clientId===ui.clientId)}
function chosenDog(){const all=myDogs();if(!all.some(d=>d.id===ui.dogId)) ui.dogId=all[0]?.id||null;return all.find(d=>d.id===ui.dogId)}
function owner(d){return db.clients.find(c=>c.id===d?.clientId)}
function getSlot(a){return db.slots.find(s=>s.id===a?.slotId)}
function getDog(id){return db.dogs.find(d=>d.id===id)}
function getClient(id){return db.clients.find(c=>c.id===id)}
function isAvailable(s){return new Date(s.start).getTime()-Date.now()>=48*HOUR && !db.appointments.some(a=>a.slotId===s.id&&['requested','confirmed','completed'].includes(a.status))}
function statusBadge(status){const m={requested:['In attesa','orange'],confirmed:['Confermato','blue'],completed:['Completato',''],cancelled:['Annullato','red']};const [label,c]=m[status]||[status,''];return `<span class="pill ${c}">${esc(label)}</span>`}
function moneyBadge(a){return `<span class="pill ${a.payment==='paid'?'':'orange'}">${a.payment==='paid'?'Pagato':a.paymentClaimedAt?'Pagamento segnalato · da verificare':'Da pagare'}</span>`}
function dogPhoto(d,klass='dog-emoji'){return `<div class="${klass}">${verifyPhoto(d?.photo)?`<img alt="Foto di ${esc(d.identity?.name||'cane')}" src="${d.photo}">`:'🐕'}</div>`}
function dogName(d){return d?.identity?.name||'Cane senza nome'}
function fieldHtml(f,v,readonly){const val=String(v??'');const id='field-'+f.key;const attrs=`name="${esc(f.key)}" id="${id}" ${readonly?'disabled':''}`;
 let control='';
 if(f.type==='textarea')control=`<textarea ${attrs} rows="3" placeholder="Aggiungi osservazioni contestuali…">${esc(val)}</textarea>`;
 else if(f.type==='score')control=`<select ${attrs}>${[['','Non valutato'],['1','1 · Richiede forte supporto'],['2','2 · In sviluppo'],['3','3 · Intermedio'],['4','4 · Buona competenza'],['5','5 · Consolidato']].map(([x,l])=>`<option value="${x}" ${x===val?'selected':''}>${l}</option>`).join('')}</select>`;
 else if(f.type==='select')control=`<select ${attrs}>${f.options.map(x=>`<option value="${esc(x)}" ${x===val?'selected':''}>${esc(x||'Seleziona…')}</option>`).join('')}</select>`;
 else control=`<input ${attrs} type="${f.type==='number'?'number':f.type==='date'?'date':'text'}" value="${esc(val)}" ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''} ${f.step?`step="${f.step}"`:''} maxlength="${f.type==='number'?'12':'500'}">`;
 return `<div class="field ${f.full?'full':''}"><label for="${id}">${esc(f.label)}</label>${control}</div>`
}
function fieldsHtml(fields,data={},readonly=false){return `<div class="grid-form">${fields.map(f=>fieldHtml(f,data[f.key],readonly)).join('')}</div>`}
function formVal(form,name){return form.elements.namedItem(name)?.value?.trim()||''}
function appTitle(){return ({dashboard:'Panoramica',clients:'Clienti',dogs:'Schede canine',dog:'Scheda del cane',appointments:'Lezioni e prenotazioni',goals:'Obiettivi',progress:'Monitoraggio',journal:'Diario delle attività',settings:'Impostazioni'})[ui.view]||'Percorso Cane'}
function navItems(){return [{id:'dashboard',icon:'◫',label:'Panoramica'},{id:'clients',icon:'♙',label:'Clienti',educator:true},{id:'dogs',icon:'🐾',label:'Cani'},{id:'appointments',icon:'▦',label:'Lezioni'},{id:'goals',icon:'◎',label:'Obiettivi'},{id:'progress',icon:'▤',label:'Progressi'},{id:'journal',icon:'✎',label:'Diario'},{id:'settings',icon:'⚙',label:'Impostazioni'}].filter(x=>!x.educator||isEducator())}

function inboxNotices(){
 return (db.notices||[]).filter(n=>n&&n.to===(isEducator()?'educator':'client')&&(isEducator()||n.clientId===ui.clientId))
   .sort((a,b)=>String(b.createdAt||'').localeCompare(String(a.createdAt||'')));
}
function pendingNoticeCount(){return inboxNotices().filter(n=>!n.readAt).length}
function pushEventNotice(to,a,kind,title,message){
 if(!Array.isArray(db.notices))db.notices=[];
 db.notices.push({id:uid(),to,clientId:a.clientId,dogId:a.dogId,appointmentId:a.id,kind,title,message,createdAt:new Date().toISOString(),readAt:null});
 if(db.notices.length>400)db.notices=db.notices.slice(-400);
}
function renderNoticeInbox(){
 const items=inboxNotices(),unread=pendingNoticeCount();
 return `<section class="panel notice-center" id="notice-center" aria-label="Notifiche del profilo">
 <div class="sectionhead" style="margin:0 0 12px"><div><h2>🔔 Notifiche ${unread?`<span class="count-notice">${unread} nuove</span>`:''}</h2><p>Eventi di prenotazione e pagamento del ${isEducator()?'professionista':'cliente'}</p></div>${unread?`<button class="btn small" type="button" data-notice-read-all>Segna tutte come lette</button>`:''}</div>
 <div class="notice-items">${items.length?items.slice(0,15).map(n=>`<div class="notice-entry ${n.readAt?'':'unread'}"><div class="notice-details"><strong>${esc(n.title)}</strong><p>${esc(n.message)}</p><small>${fmtDateTime(n.createdAt)} · ${n.readAt?'Letta':'Da leggere'}</small></div><button class="btn small ${n.readAt?'':'primary'}" type="button" data-notice-open="${esc(n.id)}">Apri</button></div>`).join(''):empty('Nessuna notifica registrata.')}</div>
 <p class="footer-hint">In questa versione demo le notifiche sono visibili soltanto sul dispositivo che registra gli eventi. Non sono notifiche push.</p>
 </section>`
}
function notifications(){const msgs=[];const appts=db.appointments.filter(a=>isEducator()||a.clientId===ui.clientId),now=Date.now();
 const requests=appts.filter(a=>a.status==='requested');
 if(isEducator()&&requests.length)msgs.push({title:'Richieste di prenotazione',body:`${requests.length} ${requests.length===1?'richiesta da confermare':'richieste da confermare'}.`,go:'appointments'});
 for(const a of appts){const s=getSlot(a);if(!s)continue;const ms=new Date(s.start).getTime()-now;if(a.status==='confirmed'&&ms>0&&ms<=48*HOUR)msgs.push({title:'Promemoria lezione',body:`${dogName(getDog(a.dogId))}: ${fmtDateTime(s.start)}.`,go:'appointments'});if(a.payment==='unpaid'&&['confirmed','completed'].includes(a.status)&&ms<=24*HOUR)msgs.push({title:'Pagamento da verificare',body:`${dogName(getDog(a.dogId))}: ${euro(s.fee)}.`,go:'appointments'})}
 return msgs.slice(0,7)
}
function sidebar(){let items=navItems(),req=db.appointments.filter(a=>a.status==='requested').length;return `<aside class="sidebar"><div class="brand"><div class="brand-logo">🐾</div><div><b>Percorso Cane</b><small>Educazione cinofila</small></div></div><div class="side-label">Area ${isEducator()?'professionista':'cliente'}</div><div class="navwrap">${items.map((x,i)=>`<button class="navbtn ${ui.view===x.id||ui.view==='dog'&&x.id==='dogs'?'active':''} ${i>5?'mobile-extra':''}" data-nav="${x.id}"><span class="nav-ico">${x.icon}</span><span>${x.label}</span>${x.id==='appointments'&&req&&isEducator()?`<span class="count">${req}</span>`:''}</button>`).join('')}</div><div class="side-bottom"><div class="mode"><p>Modalità di visualizzazione</p><select id="role-switch" aria-label="Area applicazione"><option value="educator" ${isEducator()?'selected':''}>Educatore (demo)</option><option value="client" ${!isEducator()?'selected':''}>Cliente (demo)</option></select>${!isEducator()&&db.clients.length?`<select id="client-switch" style="margin-top:8px" aria-label="Cliente">${db.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===ui.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select>`:''}</div><div class="sidebar-foot">Versione 1.0.7 · Demo locale<br>Dati salvati solo nel dispositivo</div></div></aside>`}
function clientPicker(){return !isEducator()&&db.clients.length?`<div class="client-context"><label for="client-switch-top">Visualizza cliente (demo)</label><select id="client-switch-top" aria-label="Seleziona cliente nella modalità dimostrativa">${db.clients.map(c=>`<option value="${esc(c.id)}" ${c.id===ui.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div>`:''}
function topbar(){return `<header class="topbar ${isEducator()?'':'client-mode'}"><div><div class="bread"><span class="mobile-brand">Percorso Cane · </span>${isEducator()?'Area professionista':'Area cliente'} / ${appTitle()}</div><h1 class="page-title">${appTitle()}</h1></div><div class="top-right"><button class="btn small notice-button" type="button" data-nav="dashboard" data-notice-jump title="Apri notifiche">🔔 ${pendingNoticeCount()}</button><button class="btn small role-top" data-toggle-role title="Cambia area demo">${isEducator()?'👤 Cliente':'🧑‍🏫 Educatore'}</button><span class="indicator">● Archiviazione locale</span><div class="top-user"><span>${isEducator()?'Professionista':'Cliente demo'}</span><div class="avatar">${isEducator()?'EC':'CL'}</div></div></div>${clientPicker()}</header>`}
function demoBanner(){return `<div class="demo-banner"><b>Prototipo locale 1.0.</b> I dati e i cambi di ruolo sono visibili soltanto in questo browser: non esistono account separati, sincronizzazione, incassi né notifiche push. Utilizza solo dati fittizi per il collaudo.</div>`}
function metrics(label,value,icon,sub,destination,filter){return `<button class="metric metric-link" type="button" data-nav="${destination}" ${filter?`data-dashboard-filter="${filter}"`:``} title="Apri ${esc(label)}"><div class="metric-top"><span>${esc(label)}</span><span class="metric-symbol">${icon}</span></div><strong>${value}</strong><small>${esc(sub)}</small></button>`}
function empty(msg){return `<div class="empty"><span class="big">🐾</span>${esc(msg)}</div>`}
function dogSwitcher(){const dogs=myDogs();if(!dogs.length)return '';return `<select class="selector" id="dog-switch" aria-label="Seleziona cane">${dogs.map(d=>`<option value="${d.id}" ${d.id===chosenDog()?.id?'selected':''}>${esc(dogName(d))} ${isEducator()?'· '+esc(owner(d)?.name||''):''}</option>`).join('')}</select>`}
function dogRows(dogs){return dogs.length?dogs.map(d=>`<div class="list-row">${dogPhoto(d)}<div class="grow"><b>${esc(dogName(d))}</b><small>${esc(d.identity?.breed||'Razza da completare')} · ${esc(owner(d)?.name||'')}</small></div><button class="btn small" data-open-dog="${d.id}">Apri scheda</button></div>`).join(''):empty('Non sono ancora presenti cani.')}
function renderDashboard(){const dogs=myDogs(),appts=db.appointments.filter(a=>isEducator()||a.clientId===ui.clientId),upcoming=appts.filter(a=>['requested','confirmed'].includes(a.status)&&new Date(getSlot(a)?.start).getTime()>Date.now()).sort((a,b)=>new Date(getSlot(a)?.start)-new Date(getSlot(b)?.start));
 const openAmt=appts.filter(a=>a.payment==='unpaid'&&['confirmed','completed'].includes(a.status)).reduce((n,a)=>n+(Number(getSlot(a)?.fee)||0),0);
 const notes=notifications();
 return `<div class="welcome"><div><div class="eyebrow">${isEducator()?'La tua attività in sintesi':'Il percorso del tuo cane'}</div><h2>${isEducator()?'Ogni percorso inizia dall’ascolto.':'Un passo alla volta, insieme.'}</h2><p>${isEducator()?'Gestisci osservazioni, lezioni, obiettivi e collaborazione con le famiglie in un unico spazio.':'Consulta gli obiettivi, registra la settimana e richiedi lezioni disponibili con almeno 48 ore di anticipo.'}</p></div><div style="font-size:65px;opacity:.95">🐾</div></div>
 <div class="cards">${isEducator()?metrics('Clienti',db.clients.length,'♙','Nuclei registrati','clients')+metrics('Cani',dogs.length,'🐕','Schede attive','dogs'):metrics('I miei cani',dogs.length,'🐕','Profili disponibili','dogs')+metrics('Obiettivi',db.goals.filter(g=>dogs.some(d=>d.id===g.dogId)).length,'◎','In monitoraggio','goals')}${metrics('Lezioni future',upcoming.length,'▦','Confermate o richieste','appointments','future')}${metrics('Da verificare',euro(openAmt),'€','Pagamenti non segnati come saldati','appointments','unpaid')}</div>
 ${renderNoticeInbox()}
 <div class="twocol" style="margin-top:22px"><div class="panel"><div class="sectionhead" style="margin:0 0 5px"><h2>Prossime lezioni</h2><button class="btn small" data-nav="appointments">Vai alle lezioni</button></div>${upcoming.length?upcoming.slice(0,5).map(a=>{const s=getSlot(a);return `<div class="list-row"><div class="dog-emoji">📅</div><div class="grow"><b>${esc(dogName(getDog(a.dogId)))} · ${fmtDateTime(s.start)}</b><small>${esc(s.location)} · ${euro(s.fee)}</small></div>${statusBadge(a.status)}</div>`}).join(''):empty('Nessuna lezione pianificata.')}</div><div class="panel"><div class="sectionhead" style="margin:0 0 9px"><h2>Promemoria nell’app</h2><span class="pill">${notes.length}</span></div>${notes.length?notes.map(n=>`<div class="alert ${n.title.startsWith('Promemoria')?'info':''}"><strong>${esc(n.title)}</strong>${esc(n.body)} <button class="btn link small" data-nav="${n.go}">Apri</button></div>`).join(''):empty('Al momento nessun promemoria attivo.')}<p class="footer-hint">I promemoria vengono calcolati quando apri l’app: non vengono inviati ad app chiusa.</p></div></div>
 <div class="sectionhead"><div><h2>${isEducator()?'Schede canine':'I miei cani'}</h2><p>Accesso rapido ai profili</p></div><button class="btn" data-nav="dogs">Tutte le schede</button></div><div class="panel">${dogRows(dogs.slice(0,5))}</div>`
}
function renderClients(){if(!isEducator())return empty('Area riservata al professionista.');return `<div class="sectionhead"><div><h2>Clienti e nuclei familiari</h2><p>I nominativi sono identificativi interni: per ora non esistono accessi personali.</p></div><button class="btn primary" data-modal="client">+ Nuovo cliente</button></div><div class="panel">${db.clients.length?db.clients.map(c=>{const dogs=db.dogs.filter(d=>d.clientId===c.id);return `<div class="list-row"><div class="avatar">${esc(c.name?.slice(0,1).toUpperCase())}</div><div class="grow"><b>${esc(c.name)}</b><small>${esc(c.email||'Email non indicata')} ${c.phone?'· '+esc(c.phone):''}</small><small>${dogs.length} ${dogs.length===1?'cane associato':'cani associati'}: ${esc(dogs.map(d=>dogName(d)).join(', ')||'nessuno')}</small></div><button class="btn small" data-add-dog="${esc(c.id)}">+ Cane</button></div>`}).join(''):empty('Aggiungi il primo cliente.')}</div>`}
function renderDogs(){const dogs=myDogs();return `<div class="sectionhead"><div><h2>Profili canine e contesti familiari</h2><p>${dogs.length} schede disponibili · seleziona un cane per compilarne le sezioni.</p></div>${isEducator()?`<button class="btn primary" data-modal="dog">+ Aggiungi cane</button>`:''}</div><div class="doggrid">${dogs.map(d=>{const goals=db.goals.filter(g=>g.dogId===d.id),avg=goals.length?Math.round(goals.reduce((n,g)=>n+Number(g.progress||0),0)/goals.length):0;return `<article class="dogcard"><div class="dogcard-top">${dogPhoto(d,'dogcard-photo')}<div><h3>${esc(dogName(d))}</h3><p>${esc(d.identity?.breed||'Razza non indicata')}</p><p>${esc(owner(d)?.name||'')}</p></div></div><div class="mini-meta"><span class="pill">${esc(d.identity?.ageYears||'—')} anni</span><span class="pill">${esc(d.identity?.weightKg||'—')} kg</span></div><div class="progress"><span style="width:${avg}%"></span></div><div class="dogcard-foot"><span class="note">${goals.length} obiettivi · ${avg}% medio</span><button class="btn primary small" data-open-dog="${d.id}">Apri scheda</button></div></article>`}).join('')}</div>${!dogs.length?empty('Nessun cane presente. Il professionista può aggiungere una scheda.'):''}`}
function renderDog(){const d=chosenDog();if(!d)return empty('Seleziona o aggiungi un cane.');if(!isEducator()&&ui.tab==='work')ui.tab='identity';const config=CONFIG[ui.tab]||CONFIG.identity;const canEdit=isEducator()||['identity','family','routine'].includes(ui.tab);
 const tabs=[['identity','Anagrafica'],['family','Famiglia'],['emotion','Profilo emotivo'],['skills','Competenze'],['routine','Routine'],...(isEducator()?[['work','Piano professionale']]:[])];
 return `<div class="panel"><div class="topdogbar"><div class="doghead">${dogPhoto(d,'dogcard-photo')}<div><h2>${esc(dogName(d))}</h2><p>${esc(d.identity?.breed||'Razza non indicata')} · ${esc(owner(d)?.name||'')}</p><p>${esc(d.identity?.sex||'Sesso da indicare')} · ${esc(d.identity?.ageYears||'—')} anni · ${esc(d.identity?.weightKg||'—')} kg</p></div></div><div class="actions">${isEducator()?`<button class="btn" data-modal="photo">📷 Cambia foto</button>`:`<button class="btn" data-modal="photo">📷 Foto</button>`}<button class="btn soft" data-nav="dogs">Torna ai cani</button></div></div>
 <div class="tabs">${tabs.map(([key,label])=>`<button class="tab ${ui.tab===key?'active':''}" data-tab="${key}">${label}</button>`).join('')}</div><div class="form-section"><h3>${config.title}</h3><p>${config.help}</p></div>${!canEdit?'<div class="readonly-note">Questa sezione è in sola lettura nell’area cliente.</div>':''}<form id="dog-edit" data-group="${ui.tab}" data-dog="${esc(d.id)}">${fieldsHtml(config.fields,d[ui.tab]||{},!canEdit)}${canEdit?`<div class="formactions"><span class="note">Le modifiche vengono salvate su questo dispositivo.</span><button class="btn primary" type="submit">Salva ${ui.tab==='identity'?'anagrafica':'sezione'}</button></div>`:''}</form></div>`}
function renderAppointments(){const aps=db.appointments.filter(a=>isEducator()||a.clientId===ui.clientId).sort((a,b)=>new Date(getSlot(b)?.start||0)-new Date(getSlot(a)?.start||0));const avail=db.slots.filter(isAvailable).sort((a,b)=>new Date(a.start)-new Date(b.start));const upcoming=aps.filter(a=>['requested','confirmed'].includes(a.status)&&new Date(getSlot(a)?.start)>new Date());
 const currentFilter=['all','future','unpaid'].includes(ui.appointmentFilter)?ui.appointmentFilter:'all';
 const shownAppointments=currentFilter==='future'?upcoming:currentFilter==='unpaid'?aps.filter(a=>a.payment==='unpaid'&&['confirmed','completed'].includes(a.status)):aps;
 const filterDescription=currentFilter==='future'?'Lezioni future confermate o richieste':currentFilter==='unpaid'?'Pagamenti ancora da verificare':`${upcoming.length} in programma o in attesa di conferma`;
 return `<div class="sectionhead"><div><h2>Agenda lezioni</h2><p>Prenotazioni consentite solo se mancano almeno 48 ore all’inizio.</p></div>${isEducator()?`<button class="btn primary" data-modal="slot">+ Crea disponibilità</button>`:dogSwitcher()}</div>
 ${!isEducator()?`<div class="panel" style="margin-bottom:20px"><h3>Richiedi una nuova lezione</h3><p class="note">Seleziona una disponibilità e invia la richiesta all’educatore. La lezione si svolge solo dopo conferma.</p><div class="availability">${avail.length?avail.map(s=>`<div class="slot"><b>📅 ${fmtDateTime(s.start)}</b><small>${esc(s.location)} · ${s.duration} minuti</small><div class="mini-meta"><span class="pill">${euro(s.fee)}</span><span class="pill">Disponibile</span></div><button class="btn primary" data-book="${s.id}" ${!chosenDog()?'disabled':''}>Richiedi lezione</button></div>`).join(''):empty('Nessuna disponibilità prenotabile con almeno 48 ore di preavviso.')}</div></div>`:''}
 ${isEducator()?`<div class="panel" style="margin-bottom:20px"><div class="sectionhead" style="margin:0 0 14px"><h2>Disponibilità pubblicate</h2><span class="pill">${avail.length} prenotabili</span></div><div class="availability">${db.slots.slice().sort((a,b)=>new Date(a.start)-new Date(b.start)).filter(s=>new Date(s.start).getTime()>Date.now()).map(s=>`<div class="slot"><b>${fmtDateTime(s.start)}</b><small>${esc(s.location)} · ${s.duration} minuti · ${euro(s.fee)}</small><div class="mini-meta"><span class="pill ${isAvailable(s)?'':'orange'}">${isAvailable(s)?'Prenotabile':db.appointments.some(a=>a.slotId===s.id&&a.status!=='cancelled')?'Assegnata':'Non prenotabile'}</span></div><div class="actions"><button class="btn small danger" data-delete-slot="${s.id}" ${db.appointments.some(a=>a.slotId===s.id&&a.status!=='cancelled')?'disabled':''}>Elimina</button></div></div>`).join('')||empty('Non ci sono disponibilità future.')}</div></div>`:''}
 <div class="sectionhead" id="appointment-records"><div><h2>${isEducator()?'Prenotazioni e pagamenti':'Le mie prenotazioni'}</h2><p>${esc(filterDescription)} · ${shownAppointments.length} ${shownAppointments.length===1?"risultato":"risultati"}</p></div></div><div class="appointment-filters" role="group" aria-label="Filtra le prenotazioni"><button type="button" class="btn small" data-appointment-filter="all" aria-pressed="${currentFilter==='all'}">Tutte</button><button type="button" class="btn small" data-appointment-filter="future" aria-pressed="${currentFilter==='future'}">Lezioni future</button><button type="button" class="btn small" data-appointment-filter="unpaid" aria-pressed="${currentFilter==='unpaid'}">Da verificare</button></div><div class="panel"><div class="tablewrap"><table class="table"><thead><tr><th>Data e ora</th><th>Cane e cliente</th><th>Stato</th><th>Importo</th><th>Azioni</th></tr></thead><tbody>${shownAppointments.length?shownAppointments.map(a=>{const s=getSlot(a),d=getDog(a.dogId);return `<tr data-appointment-row="${esc(a.id)}"><td><b>${fmtDateTime(s?.start)}</b><br><small class="muted">${esc(s?.location||'')}</small></td><td>${esc(dogName(d))}<br><small class="muted">${esc(getClient(a.clientId)?.name||'')}</small></td><td>${statusBadge(a.status)}</td><td>${euro(s?.fee)}<br>${moneyBadge(a)}</td><td><div class="actions" style="justify-content:flex-end">${isEducator()?`${a.status==='requested'?`<button class="btn small primary" data-apt-action="confirm" data-id="${a.id}">Conferma</button><button class="btn small" data-apt-action="cancel" data-id="${a.id}">Rifiuta</button>`:''}${a.status==='confirmed'?`<button class="btn small" data-apt-action="complete" data-id="${a.id}">Concludi</button>`:''}${['confirmed','completed'].includes(a.status)&&a.payment!=='paid'?`<button class="btn small soft" data-apt-action="paid" data-id="${a.id}">Segna pagato</button>`:''}`:a.status==='requested'?`<button class="btn small danger" data-apt-action="cancel" data-id="${a.id}">Annulla richiesta</button>`:['confirmed','completed'].includes(a.status)&&a.payment==='unpaid'?(a.paymentClaimedAt?`<span class="pill orange">Pagamento segnalato</span>`:`<button class="btn small soft" type="button" data-apt-action="claim_paid" data-id="${a.id}">Ho effettuato il pagamento</button>`):''}</div></td></tr>`}).join(''):`<tr><td colspan="5">${currentFilter==='future'?'Nessuna lezione futura.':currentFilter==='unpaid'?'Nessun pagamento da verificare.':'Nessuna prenotazione registrata.'}</td></tr>`}</tbody></table></div></div><p class="footer-hint">Pagamenti: registro manuale di importi e stato; non viene eseguita alcuna transazione. Nessun reminder viene inviato via email, SMS o push.</p>`
}
function goalsForDog(d){return db.goals.filter(g=>g.dogId===d?.id)}
function goalCard(g){const progress=Math.max(0,Math.min(100,Number(g.progress)||0));return `<div class="goalrow"><div class="goalhead"><b>${esc(g.title)}</b><span>${progress}%</span></div>${g.description?`<p class="note" style="margin:0 0 9px">${esc(g.description)}</p>`:''}<div class="progress"><span style="width:${progress}%"></span></div><div class="row-gap" style="justify-content:space-between;margin-top:9px"><div class="mini-meta"><span class="pill">${esc(g.area||'Percorso')}</span>${g.targetDate?`<span class="pill">Entro ${fmtDate(g.targetDate)}</span>`:''}</div>${isEducator()?`<div class="actions"><button class="btn small" data-update-goal="${g.id}">Aggiorna</button><button class="btn small danger" data-delete-goal="${g.id}">Elimina</button></div>`:''}</div></div>`}
function renderGoals(){const d=chosenDog();const goals=goalsForDog(d),avg=goals.length?Math.round(goals.reduce((n,g)=>n+Number(g.progress||0),0)/goals.length):0;return `<div class="sectionhead"><div><h2>Obiettivi del percorso</h2><p>Gli avanzamenti sono valutazioni condivisibili, inserite manualmente dal professionista.</p></div><div class="actions">${dogSwitcher()}${isEducator()&&d?`<button class="btn primary" data-modal="goal">+ Nuovo obiettivo</button>`:''}</div></div>${!d?empty('Seleziona un cane per iniziare.'):`<div class="twocol"><div class="panel"><h3>Obiettivi di ${esc(dogName(d))}</h3>${goals.length?goals.map(goalCard).join(''):empty('Nessun obiettivo definito.')}</div><div class="panel"><h3>Panoramica del percorso</h3><div class="center" style="padding:20px"><div style="border:13px solid #e8eee8;border-top-color:#528773;border-right-color:#528773;border-radius:50%;height:164px;width:164px;display:grid;place-items:center"><div style="text-align:center"><strong style="font-size:31px">${avg}%</strong><br><small class="note">Media obiettivi</small></div></div></div><p class="note">La media è puramente descrittiva: non costituisce un indice clinico o scientificamente validato. Ogni obiettivo va interpretato nel suo contesto.</p><button class="btn soft" data-nav="progress">Apri andamento settimanale</button></div></div>`}`}
function renderChart(checkins){const sorted=checkins.slice().sort((a,b)=>a.week.localeCompare(b.week)).slice(-8);return sorted.length?`<div class="chart-wrap"><div class="chart">${sorted.map(c=>`<div class="chart-item"><strong>${Number(c.score)}/5</strong><div class="bar" style="height:${Number(c.score)*18}%"></div><label>${fmtDate(c.week).replace(/ \d{4}/,'')}</label></div>`).join('')}</div></div>`:empty('Non sono ancora presenti rilevazioni settimanali.')}
function renderProgress(){const d=chosenDog();if(!d)return empty('Nessun cane selezionato.');const checks=db.checkins.filter(c=>c.dogId===d.id).sort((a,b)=>b.week.localeCompare(a.week));return `<div class="sectionhead"><div><h2>Andamento settimanale</h2><p>Autovalutazione indicativa da 1 (settimana difficile) a 5 (settimana serena).</p></div><div class="actions">${dogSwitcher()}<button class="btn primary" data-modal="checkin">+ Registra settimana</button></div></div><div class="twocol"><div class="panel"><h3>Andamento di ${esc(dogName(d))}</h3>${renderChart(checks)}<p class="footer-hint">I valori sono soggettivi, non equivalgono a una diagnosi né a una misura clinica.</p></div><div class="panel"><h3>Ultime rilevazioni</h3>${checks.length?checks.slice(0,5).map(c=>`<div class="list-row"><div class="avatar">${c.score}/5</div><div class="grow"><b>Settimana del ${fmtDate(c.week)}</b><small>${esc(c.notes||'Nessuna osservazione')}</small>${c.homework?`<small>Da approfondire: ${esc(c.homework)}</small>`:''}</div></div>`).join(''):empty('Nessuna rilevazione salvata.')}</div></div>`}
function renderJournal(){const dogs=myDogs(),entry=db.journal.filter(j=>dogs.some(d=>d.id===j.dogId)&&(isEducator()||j.share)).sort((a,b)=>b.date.localeCompare(a.date));return `<div class="sectionhead"><div><h2>Registro delle attività</h2><p>${isEducator()?'Documenta cosa è stato fatto, cosa pianificare e le difficoltà osservate.':'Riepiloghi delle lezioni condivisi dal professionista.'}</p></div>${isEducator()?`<div class="actions">${dogSwitcher()}<button class="btn primary" data-modal="journal">+ Nota di lezione</button></div>`:dogSwitcher()}</div><div class="panel"><div class="timeline">${entry.length?entry.map(j=>`<div class="timeline-item"><small>${fmtDate(j.date)} · ${esc(dogName(getDog(j.dogId)))}</small><h4>Attività svolte</h4><p>${esc(j.activity||'Non indicate')}</p>${j.next?`<h4>Da lavorare alla prossima sessione</h4><p>${esc(j.next)}</p>`:''}${j.difficulty?`<h4>Difficoltà osservate</h4><p>${esc(j.difficulty)}</p>`:''}${isEducator()&&j.privateNote?`<div class="alert"><strong>Nota interna · non condivisa nell’area cliente</strong>${esc(j.privateNote)}</div>`:''}<span class="pill ${j.share?'':'orange'}">${j.share?'Riepilogo condivisibile':'Solo professionista'}</span></div>`).join(''):empty('Non sono ancora disponibili note di lezione.')}</div></div>`}
function renderSettings(){return `<div class="sectionhead"><div><h2>Configurazione e backup</h2><p>Versione dimostrativa · archiviazione locale nel browser</p></div><span class="pill">v1.0.7</span></div><div class="settings-grid"><div class="panel"><h3>💾 Esporta i dati</h3><p class="note">Salva un archivio JSON contenente clienti, schede canine, appuntamenti, progressi e diario. Il backup non è cifrato: custodiscilo con attenzione.</p><button class="btn primary" data-action="export">Scarica backup JSON</button></div><div class="panel"><h3>↥ Importa backup</h3><p class="note">Ripristina un file JSON creato con questa app. I dati attuali saranno sostituiti; esporta prima una copia.</p><div class="field"><label for="backup-file">Scegli un file di backup</label><input id="backup-file" type="file" accept=".json,application/json"></div></div><div class="panel"><h3>📋 Stampa / salva PDF</h3><p class="note">Per ottenere una copia della schermata corrente, usa la funzione di stampa del browser. Per ora non è disponibile un referto strutturato.</p><button class="btn" data-action="print">Stampa schermata</button></div><div class="panel"><h3>↺ Ripristina dati demo</h3><p class="note">Sostituisce tutti i dati locali con i profili fittizi di collaudo.</p><button class="btn danger" data-action="reset">Ripristina esempio</button></div></div><div class="panel" style="margin-top:17px"><h3>Prima di usare l’app con clienti reali</h3><p class="note">Questa versione <b>non offre autenticazione, autorizzazioni, cifratura applicativa, audit log, sincronizzazione né garanzie di conservazione</b>. I dettagli su salute, famiglia e note sulle persone possono contenere dati personali e informazioni particolarmente delicate. Per un servizio operativo servono server protetto, ruoli separati e verificati, informative privacy e misure tecniche e organizzative adeguate.</p><p class="note">Le regole di prenotazione usano l’ora di questo dispositivo. Per prevenire elusioni e prenotazioni concorrenti, la validazione deve passare a un server.</p></div>`}
function modalContents(){const d=chosenDog(),m=ui.modal;if(!m)return '';let title='',sub='',body='';
 if(m==='client'){title='Nuovo cliente';sub='Crea un nucleo familiare prima di associare un cane.';body=`<form id="create-client"><div class="grid-form">${fieldsHtml([field('name','Nome e cognome'),field('email','Email'),field('phone','Telefono')])}</div><div class="formactions"><button class="btn primary" type="submit">Crea cliente</button></div></form>`}
 if(m==='dog'){title='Nuova scheda cane';sub='Associa il cane a un cliente: il resto della scheda sarà compilabile dopo il salvataggio.';body=`<form id="create-dog"><div class="grid-form"><div class="field"><label for="new-client">Cliente *</label><select id="new-client" name="clientId" required>${db.clients.map(c=>`<option value="${c.id}" ${c.id===ui.clientId?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="new-dog-name">Nome del cane *</label><input id="new-dog-name" name="name" maxlength="100" required></div><div class="field"><label for="new-dog-breed">Razza / mix</label><input id="new-dog-breed" name="breed" maxlength="100"></div></div><div class="formactions"><button class="btn primary" type="submit">Crea scheda</button></div></form>`}
 if(m==='slot'){title='Nuova disponibilità';sub='Le richieste possono essere inviate soltanto fino a 48 ore prima della lezione.';body=`<form id="create-slot"><div class="grid-form"><div class="field"><label for="slot-date">Data e ora *</label><input id="slot-date" type="datetime-local" name="start" value="${plusDays(4)}" required></div><div class="field"><label for="slot-duration">Durata (minuti)</label><select name="duration" id="slot-duration"><option>45</option><option selected>60</option><option>90</option><option>120</option></select></div><div class="field"><label for="slot-location">Luogo o tipologia</label><input id="slot-location" name="location" value="Campo educativo" maxlength="150"></div><div class="field"><label for="slot-fee">Tariffa (€)</label><input id="slot-fee" type="number" name="fee" value="45" min="0" max="9999" step="0.01"></div></div><div class="formactions"><button class="btn primary" type="submit">Pubblica disponibilità</button></div></form>`}
 if(m==='goal'){title='Nuovo obiettivo';sub=`Percorso di ${dogName(d)} · definisci una competenza osservabile e raggiungibile.`;body=`<form id="create-goal"><div class="grid-form">${fieldsHtml([field('title','Titolo obiettivo'),field('area','Area di lavoro','select',['','Autoregolazione','Relazione','Socializzazione','Routine','Collaborazione','Autonomia','Altro']),field('description','Criteri di raggiungimento','textarea',{full:true}),field('targetDate','Data obiettivo (facoltativa)','date')])}</div><div class="formactions"><button class="btn primary" type="submit">Aggiungi obiettivo</button></div></form>`}
 if(m==='update-goal'){const g=db.goals.find(g=>g.id===ui.goalId);if(!g){ui.modal=null;return ''}title='Aggiorna il progresso';sub=esc(g.title);body=`<form id="update-goal"><div class="field"><label for="goal-progress">Stima di raggiungimento (0–100%)</label><input id="goal-progress" type="number" name="progress" min="0" max="100" step="5" value="${Number(g.progress)||0}" required><small>Valutazione professionale contestualizzata, non score clinico.</small></div><div class="formactions"><button class="btn primary" type="submit">Salva progresso</button></div></form>`}
 if(m==='checkin'){title='Monitoraggio settimanale';sub=`Cane: ${dogName(d)} · inserisci una rilevazione condivisibile.`;body=`<form id="create-checkin"><div class="grid-form"><div class="field"><label for="checkin-week">Settimana (lunedì di riferimento)</label><input id="checkin-week" name="week" type="date" value="${weekKey(new Date())}" required></div><div class="field"><label for="checkin-score">Come è andata questa settimana?</label><select id="checkin-score" name="score"><option value="1">1 · Molto impegnativa</option><option value="2">2 · Impegnativa</option><option value="3" selected>3 · Nella media</option><option value="4">4 · Positiva</option><option value="5">5 · Molto positiva</option></select></div>${fieldsHtml([field('notes','Osservazioni della settimana','textarea',{full:true}),field('homework','Attività, difficoltà o aspetti su cui lavorare','textarea',{full:true})])}</div><div class="formactions"><button class="btn primary" type="submit">Salva settimana</button></div></form>`}
 if(m==='journal'){title='Nuova nota di lezione';sub=`Registro attività · ${dogName(d)}. Le note interne non saranno mostrate nella vista cliente.`;body=`<form id="create-journal"><div class="grid-form"><div class="field"><label for="journal-date">Data della sessione *</label><input id="journal-date" name="date" type="date" value="${dateKey(new Date())}" required></div><div></div>${fieldsHtml([field('activity','Cosa abbiamo fatto *','textarea',{full:true}),field('next','Su cosa lavorare nella prossima sessione','textarea',{full:true}),field('difficulty','Difficoltà e criticità osservate','textarea',{full:true}),field('privateNote','Note interne sul cliente / professionista','textarea',{full:true})])}<div class="field full"><label for="journal-share"><input id="journal-share" name="share" type="checkbox" checked style="width:auto;min-height:auto;margin-right:7px">Condividi il riepilogo (escluse le note interne) nella vista cliente</label></div></div><div class="formactions"><button class="btn primary" type="submit">Salva nota</button></div></form>`}
 if(m==='photo'){title='Foto del cane';sub='L’immagine viene ridimensionata per non saturare rapidamente la memoria locale.';body=`<div class="field"><label for="dog-photo-file">Seleziona un’immagine JPG, PNG o WEBP</label><input type="file" id="dog-photo-file" accept="image/jpeg,image/png,image/webp"></div>${d?.photo?`<div class="formactions"><button class="btn danger" data-action="remove-photo">Rimuovi foto</button></div>`:''}`}
 if(!title)return '';return `<div class="modalback" id="modalback"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-title"><div><h2>${title}</h2><p>${sub}</p></div><button class="close" data-close aria-label="Chiudi">×</button></div>${body}</div></div>`
}

/* Keep the selected dog-section tab visible after each template render. */
function alignSelectedDogTab(){
 if(ui.view!=='dog')return;
 const strip=document.querySelector('.tabs');
 const selected=strip?.querySelector('.tab.active');
 if(!strip||!selected)return;
 const outer=strip.getBoundingClientRect();
 const inner=selected.getBoundingClientRect();
 const left=strip.scrollLeft+inner.left-outer.left;
 const desired=left-(strip.clientWidth-inner.width)/2;
 const maxLeft=Math.max(0,strip.scrollWidth-strip.clientWidth);
 strip.scrollLeft=Math.min(maxLeft,Math.max(0,desired));
}

/* iOS Safari uses a smaller visual viewport while the keyboard is on screen.
   Scroll only the focused field into the visible area, leaving native pinch zoom intact. */
function isEditableField(node){
 return node instanceof HTMLElement &&
   node.matches('textarea,select,input:not([type="checkbox"]):not([type="radio"]):not([type="file"]):not([type="hidden"]):not([type="button"]):not([type="submit"])');
}
let inputViewportFrame=0;
function updateInputViewport(){
 if(window.innerWidth>720){
  document.body.classList.remove('is-editing');
  document.documentElement.style.removeProperty('--keyboard-inset');
  return;
 }
 const focused=document.activeElement;
 const editing=isEditableField(focused);
 const vv=window.visualViewport;
 const visibleHeight=vv?.height||window.innerHeight;
 const visibleTop=vv?.offsetTop||0;
 const keyboardSpace=Math.max(0,Math.round(window.innerHeight-visibleHeight-visibleTop));
 document.body.classList.toggle('is-editing',editing);
 document.documentElement.style.setProperty('--keyboard-inset',editing?keyboardSpace+'px':'0px');
 document.documentElement.style.setProperty('--visible-viewport-height',Math.round(visibleHeight)+'px');
 document.documentElement.style.setProperty('--visible-viewport-top',Math.round(visibleTop)+'px');
 if(!editing)return;
 const fieldRect=focused.getBoundingClientRect();
 const margin=22;
 const modal=focused.closest('.modal');
 if(modal){
  const modalRect=modal.getBoundingClientRect();
  const safeTop=Math.max(visibleTop+margin,modalRect.top+margin);
  const safeBottom=Math.min(visibleTop+visibleHeight-margin,modalRect.bottom-margin);
  if(fieldRect.bottom>safeBottom)modal.scrollTop+=fieldRect.bottom-safeBottom;
  else if(fieldRect.top<safeTop)modal.scrollTop+=fieldRect.top-safeTop;
 }else{
  const safeTop=visibleTop+margin;
  const safeBottom=visibleTop+visibleHeight-margin;
  if(fieldRect.bottom>safeBottom)window.scrollBy(0,Math.ceil(fieldRect.bottom-safeBottom));
  else if(fieldRect.top<safeTop)window.scrollBy(0,Math.floor(fieldRect.top-safeTop));
 }
}
function scheduleInputViewport(){
 if(inputViewportFrame)cancelAnimationFrame(inputViewportFrame);
 inputViewportFrame=requestAnimationFrame(()=>{
  inputViewportFrame=0;
  updateInputViewport();
 });
}
function onEditorFocus(e){
 if(!isEditableField(e.target))return;
 document.body.classList.add('is-editing');
 scheduleInputViewport();
 setTimeout(scheduleInputViewport,120);
 setTimeout(scheduleInputViewport,360);
}
function onEditorBlur(){
 setTimeout(scheduleInputViewport,80);
}

function render(){const app=$('#app');if(!app)return;let body;
 switch(ui.view){case 'clients':body=renderClients();break;case 'dogs':body=renderDogs();break;case 'dog':body=renderDog();break;case 'appointments':body=renderAppointments();break;case 'goals':body=renderGoals();break;case 'progress':body=renderProgress();break;case 'journal':body=renderJournal();break;case 'settings':body=renderSettings();break;default:body=renderDashboard()}
 app.innerHTML=`<div class="layout">${sidebar()}<main class="main">${topbar()}<div class="content">${demoBanner()}${body}<p class="footer-hint">Percorso Cane v1.0.7 · nome provvisorio · prototipo funzionale per collaudo</p></div></main></div>${modalContents()}${ui.toast?`<div class="toast" role="status">${esc(ui.toast)}</div>`:''}`;
 if(ui.view==='dog')requestAnimationFrame(alignSelectedDogTab);
}
function go(page){const valid=['dashboard','clients','dogs','dog','appointments','goals','progress','journal','settings'];if(!valid.includes(page))return;if(page==='clients'&&!isEducator())return;ui.view=page;ui.modal=null;render();window.scrollTo(0,0)}
function setRole(role){if(role==='client'){const selectedDog=db.dogs.find(d=>d.id===ui.dogId);if(selectedDog&&getClient(selectedDog.clientId))ui.clientId=selectedDog.clientId;}ui.role=role==='client'?'client':'educator';ui.modal=null;ui.view='dashboard';ui.tab='identity';ui.appointmentFilter='all';chosenDog();render()}
function doBook(slotId){const s=db.slots.find(x=>x.id===slotId),d=chosenDog();if(isEducator()||!d||!s)return notify('Seleziona un cane prima di richiedere una lezione.');if(!isAvailable(s))return notify('Prenotazione non consentita: disponibilità occupata o meno di 48 ore.');
 const a={id:uid(),slotId:s.id,dogId:d.id,clientId:ui.clientId,status:'requested',payment:'unpaid',requestedAt:new Date().toISOString()};
 db.appointments.push(a);
 pushEventNotice('educator',a,'booking_requested','Nuova richiesta di lezione',`${getClient(a.clientId)?.name||'Cliente'} · ${dogName(d)} · ${fmtDateTime(s.start)}.`);
 save();notify('Richiesta inviata: nuova notifica nella Dashboard Educatore (solo su questo dispositivo).')
}
function aptAction(id,act){const a=db.appointments.find(x=>x.id===id);if(!a)return;
 const slot=getSlot(a),description=`${dogName(getDog(a.dogId))} · ${fmtDateTime(slot?.start)} · ${euro(slot?.fee)}.`;
 if(act==='claim_paid'){
   if(isEducator()||a.clientId!==ui.clientId||!['confirmed','completed'].includes(a.status)||a.payment==='paid'||a.paymentClaimedAt)return;
   if(!confirm('Confermi di aver effettuato il pagamento? Questa è una segnalazione: solo l’educatore potrà confermarne la ricezione.'))return;
   a.paymentClaimedAt=new Date().toISOString();
   pushEventNotice('educator',a,'payment_reported','Pagamento segnalato dal cliente',`${getClient(a.clientId)?.name||'Cliente'} segnala il pagamento · ${description} Da verificare.`);
   save();notify('Pagamento segnalato all’educatore. In attesa di verifica.');return;
 }
 if(act==='cancel'&&a.status==='requested'&&((isEducator())||a.clientId===ui.clientId)){
   a.status='cancelled';
   if(isEducator())pushEventNotice('client',a,'booking_declined','Richiesta di lezione non accettata',description);
   else pushEventNotice('educator',a,'booking_cancelled','Richiesta annullata dal cliente',description);
 }else if(isEducator()&&act==='confirm'&&a.status==='requested'){
   a.status='confirmed';
   pushEventNotice('client',a,'booking_confirmed','Lezione confermata dall’educatore',description);
 }else if(isEducator()&&act==='complete'&&a.status==='confirmed'){
   a.status='completed';
 }else if(isEducator()&&act==='paid'&&['confirmed','completed'].includes(a.status)&&a.payment!=='paid'){
   a.payment='paid';
   a.paymentVerifiedAt=new Date().toISOString();
   pushEventNotice('client',a,'payment_confirmed','Pagamento confermato dall’educatore',description);
 }else return;
 save();notify('Stato della lezione aggiornato.')
}
function safeBackupParse(json){const v=JSON.parse(json);if(!v||v.version!==1||!['clients','dogs','slots','appointments','goals','checkins','journal'].every(k=>Array.isArray(v[k])))throw Error('Backup non valido o versione incompatibile');if(v.dogs.length>3000||json.length>10_000_000)throw Error('Il file supera i limiti di importazione');for(const d of v.dogs){if(typeof d.id!=='string'||typeof d.clientId!=='string'||!d.identity||typeof d.identity!=='object')throw Error('Struttura delle schede canine non valida');if(d.photo&&!verifyPhoto(d.photo))d.photo=''}if(!Array.isArray(v.notices))v.notices=[];v.notices=v.notices.filter(n=>n&&typeof n.id==='string'&&['educator','client'].includes(n.to)&&typeof n.title==='string'&&typeof n.message==='string').slice(-400);return v}
function exportBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),link=document.createElement('a'),url=URL.createObjectURL(blob);link.href=url;link.download=`PercorsoCane_backup_${dateKey(new Date())}.json`;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup JSON preparato per il download. Conservalo in un luogo sicuro.')}
function onClick(e){const t=e.target.closest('[data-nav],[data-open-dog],[data-tab],[data-modal],[data-close],[data-book],[data-apt-action],[data-update-goal],[data-delete-goal],[data-delete-slot],[data-add-dog],[data-action],[data-toggle-role],[data-appointment-filter],[data-notice-open],[data-notice-read-all]');if(!t){if(e.target.id==='modalback'){ui.modal=null;render()}return}
 if(t.dataset.nav){ui.appointmentFilter=t.dataset.nav==='appointments'&&t.dataset.dashboardFilter?t.dataset.dashboardFilter:'all';go(t.dataset.nav);if(t.dataset.dashboardFilter){requestAnimationFrame(()=>document.getElementById('appointment-records')?.scrollIntoView({block:'start',behavior:'auto'}))}if(t.hasAttribute('data-notice-jump'))requestAnimationFrame(()=>document.getElementById('notice-center')?.scrollIntoView({block:'start',behavior:'smooth'}));return}
 if(t.dataset.appointmentFilter){ui.appointmentFilter=t.dataset.appointmentFilter;render();return}
 if(t.hasAttribute('data-notice-read-all')){let changed=false;for(const n of inboxNotices()){if(!n.readAt){n.readAt=new Date().toISOString();changed=true}}if(changed)save();render();requestAnimationFrame(()=>document.getElementById('notice-center')?.scrollIntoView({block:'start'}));return}
 if(t.dataset.noticeOpen){const n=inboxNotices().find(x=>x.id===t.dataset.noticeOpen);if(!n)return;if(!n.readAt){n.readAt=new Date().toISOString();save()}if(n.dogId&&myDogs().some(d=>d.id===n.dogId))ui.dogId=n.dogId;ui.appointmentFilter='all';go('appointments');requestAnimationFrame(()=>{const row=[...document.querySelectorAll('[data-appointment-row]')].find(row=>row.dataset.appointmentRow===n.appointmentId);(row||document.getElementById('appointment-records'))?.scrollIntoView({block:'center',behavior:'smooth'})});return}
 if(t.dataset.openDog){ui.dogId=t.dataset.openDog;ui.tab='identity';go('dog');return}
 if(t.dataset.tab){if(!isEducator()&&t.dataset.tab==='work')return;ui.tab=t.dataset.tab;render();return}
 if(t.dataset.modal){ui.modal=t.dataset.modal;render();return}
 if(t.hasAttribute('data-close')){ui.modal=null;render();return}
 if(t.dataset.book){doBook(t.dataset.book);return}
 if(t.dataset.aptAction){aptAction(t.dataset.id,t.dataset.aptAction);return}
 if(t.dataset.updateGoal){ui.goalId=t.dataset.updateGoal;ui.modal='update-goal';render();return}
 if(t.dataset.deleteGoal){if(!isEducator())return;if(confirm('Eliminare definitivamente questo obiettivo?')){db.goals=db.goals.filter(g=>g.id!==t.dataset.deleteGoal);save();notify('Obiettivo eliminato.')}return}
 if(t.dataset.deleteSlot){if(!isEducator())return;const id=t.dataset.deleteSlot;if(db.appointments.some(a=>a.slotId===id&&a.status!=='cancelled'))return notify('La disponibilità ha una prenotazione associata.');if(confirm('Eliminare questa disponibilità?')){db.slots=db.slots.filter(s=>s.id!==id);save();notify('Disponibilità eliminata.')}return}
 if(t.dataset.addDog){ui.clientId=t.dataset.addDog;ui.modal='dog';render();return}
 if(t.hasAttribute('data-toggle-role')){setRole(isEducator()?'client':'educator');return}
 if(t.dataset.action==='export'){exportBackup();return}
 if(t.dataset.action==='print'){window.print();return}
 if(t.dataset.action==='reset'){if(confirm('ATTENZIONE: tutti i dati locali verranno sostituiti dai dati di esempio. Proseguire?')){db=seed();ui.clientId=db.clients[0].id;ui.dogId=db.dogs[0].id;save();notify('Dati dimostrativi ripristinati.')}return}
 if(t.dataset.action==='remove-photo'){const d=chosenDog();if(d)d.photo='';save();ui.modal=null;notify('Foto rimossa.');return}
}
function onSubmit(e){const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const id=f.id;
 if(id==='dog-edit'){const d=chosenDog(),group=f.dataset.group;if(!d||!CONFIG[group]||(!isEducator()&&!['identity','family','routine'].includes(group)))return;const values={};for(const config of CONFIG[group].fields){values[config.key]=formVal(f,config.key)}d[group]={...(d[group]||{}),...values};save();notify('Sezione salvata con successo.');return}
 if(id==='create-client'){if(!isEducator())return;const name=formVal(f,'name');if(!name)return notify('Indica il nome del cliente.');const c={id:uid(),name,email:formVal(f,'email'),phone:formVal(f,'phone')};db.clients.push(c);ui.clientId=c.id;ui.modal=null;save();notify('Cliente creato. Ora puoi aggiungere il cane.');return}
 if(id==='create-dog'){if(!isEducator())return;const clientId=formVal(f,'clientId'),name=formVal(f,'name');if(!getClient(clientId)||!name)return notify('Completa il cliente e il nome del cane.');const d={id:uid(),clientId,photo:'',identity:{name,breed:formVal(f,'breed')},family:{},emotion:{},skills:{},routine:{},work:{}};db.dogs.push(d);ui.dogId=d.id;ui.clientId=clientId;ui.tab='identity';ui.modal=null;save();go('dog');notify('Scheda creata. Puoi completarla adesso.');return}
 if(id==='create-slot'){if(!isEducator())return;const start=formVal(f,'start'),ts=new Date(start).getTime(),fee=Number(formVal(f,'fee')),duration=Number(formVal(f,'duration'));if(!Number.isFinite(ts)||ts-Date.now()<48*HOUR)return notify('Scegli un orario almeno 48 ore nel futuro.');if(!Number.isFinite(fee)||fee<0||fee>9999)return notify('Importo non valido.');if(db.slots.some(s=>Math.abs(new Date(s.start).getTime()-ts)<30*60000))return notify('Esiste già una disponibilità in questo intervallo.');db.slots.push({id:uid(),start,duration,location:formVal(f,'location')||'Da concordare',fee});ui.modal=null;save();notify('Nuova disponibilità aggiunta.');return}
 if(id==='create-goal'){if(!isEducator()||!chosenDog())return;const title=formVal(f,'title');if(!title)return notify('Indica un titolo per l’obiettivo.');db.goals.push({id:uid(),dogId:chosenDog().id,title,description:formVal(f,'description'),area:formVal(f,'area'),targetDate:formVal(f,'targetDate'),progress:0});ui.modal=null;save();notify('Obiettivo aggiunto.');return}
 if(id==='update-goal'){if(!isEducator())return;const g=db.goals.find(x=>x.id===ui.goalId),v=Number(formVal(f,'progress'));if(!g||!Number.isFinite(v)||v<0||v>100)return notify('Valore non valido.');g.progress=v;ui.modal=null;save();notify('Progresso aggiornato.');return}
 if(id==='create-checkin'){const d=chosenDog();if(!d)return;const week=weekKey(formVal(f,'week')),score=Number(formVal(f,'score'));if(!Number.isFinite(score)||score<1||score>5||isNaN(new Date(week).getTime()))return notify('Data o valutazione non valida.');const old=db.checkins.find(c=>c.week===week&&c.dogId===d.id);const record={id:old?.id||uid(),dogId:d.id,week,score,notes:formVal(f,'notes'),homework:formVal(f,'homework')};if(old)Object.assign(old,record);else db.checkins.push(record);ui.modal=null;save();notify(old?'Settimana aggiornata.':'Settimana registrata.');return}
 if(id==='create-journal'){if(!isEducator()||!chosenDog())return;const activity=formVal(f,'activity');if(!activity)return notify('Inserisci le attività svolte.');db.journal.push({id:uid(),dogId:chosenDog().id,date:formVal(f,'date'),activity,next:formVal(f,'next'),difficulty:formVal(f,'difficulty'),privateNote:formVal(f,'privateNote'),share:!!f.elements.namedItem('share')?.checked});ui.modal=null;save();notify('Nota di lezione salvata.');return}
}
async function onChange(e){const t=e.target;
 if(t.id==='role-switch'){setRole(t.value);return}
 if(t.id==='client-switch'||t.id==='client-switch-top'){if(!isEducator()&&getClient(t.value)){ui.clientId=t.value;ui.dogId=db.dogs.find(d=>d.clientId===t.value)?.id||null;ui.tab='identity';chosenDog();render()}return}
 if(t.id==='dog-switch'){ui.dogId=t.value;render();return}
 if(t.id==='backup-file'&&t.files?.length){try{const raw=await t.files[0].text();const candidate=safeBackupParse(raw);if(!confirm('Sostituire tutti i dati attuali con il backup selezionato?'))return;db=candidate;ui.clientId=db.clients[0]?.id||null;ui.dogId=db.dogs[0]?.id||null;save();notify('Backup importato con successo.')}catch(err){notify('Importazione non riuscita: '+err.message)}return}
 if(t.id==='dog-photo-file'&&t.files?.length){const d=chosenDog(),file=t.files[0];if(!d||!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15_000_000){notify('Utilizza un’immagine JPG, PNG o WEBP inferiore a 15 MB.');return}try{const url=URL.createObjectURL(file),im=new Image();im.onload=()=>{const scale=Math.min(1,540/Math.max(im.width,im.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));const ctx=canvas.getContext('2d');ctx.drawImage(im,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.76);URL.revokeObjectURL(url);if(data.length>850000){notify('Foto troppo grande per la memoria locale.');return}d.photo=data;save();ui.modal=null;notify('Foto aggiornata.');};im.onerror=()=>{URL.revokeObjectURL(url);notify('Immagine non leggibile.');};im.src=url}catch{notify('Non è stato possibile leggere la foto.')}return}
}
const app=document.querySelector('#app');app.addEventListener('click',onClick);app.addEventListener('submit',onSubmit);app.addEventListener('change',onChange);
app.addEventListener('focusin',onEditorFocus);app.addEventListener('focusout',onEditorBlur);
window.visualViewport?.addEventListener('resize',scheduleInputViewport);
window.visualViewport?.addEventListener('scroll',scheduleInputViewport);
window.addEventListener('resize',scheduleInputViewport);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){ui.modal=null;render()}});
if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js', {updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{});
render();
})();